// Hand-authored public navigation — the single source of truth for the header menu
// and footer. Intentionally NOT generated by scripts/generate-content.mjs (unlike
// src/content/nav.ts, which mirrors the old WordPress menu). Each leaf references a
// content `key`; hrefs are resolved via pathForKey(key, locale) so the clean
// canonical URLs (src/site/canonical.json) stay the single URL authority.
import type { Localized } from '@/types/content'

export interface NavItem {
  /** Content key → href via pathForKey. Omit for non-navigating group headers. */
  key?: string
  label: Localized
  children?: NavItem[]
}

